    def _restore_netact_node_data_to_local(self, tool_config):
        # Backup the existing hosts file from the local
        backup_command = "sudo cp /etc/hosts /etc/hosts_temporarily_backed_up"
        proc = subprocess.Popen(backup_command, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, shell=True)
        put_val = proc.communicate()
        logger.debug("{}".format(put_val))

        # copy /etc/hosts from corresponding netact server to local /etc/hosts_retored_from_netact
        command = "sudo sshpass -p {} scp {}@{}:/etc/hosts /etc/hosts_restored_from_netact".format(
            tool_config['was_ssh_pass'], tool_config['was_ssh_user'], tool_config['was_host'])
        proc = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
        put_val = proc.communicate()
        logger.debug("{}".format(put_val))

        # append to /etc/hosts from /etc/hosts_restored_from_netact on the setup pc
        append_command = "sudo bash -c 'cat /etc/hosts_restored_from_netact >> /etc/hosts'"
        proc = subprocess.Popen(append_command, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                shell=True)
        proc.communicate()

    def _restore_hosts_on_setup_pc(self):
        backup_command = "sudo cp /etc/hosts_temporarily_backed_up /etc/hosts"
        proc = subprocess.Popen(backup_command, stdout=subprocess.PIPE,
                                stderr=subprocess.PIPE, shell=True)
        proc.communicate()

    def upload_file_to_node(self, **kwargs):
        """Upload file to node"""
        node_type = kwargs.get('node_type', 'was_node')
        local_file = kwargs.get('local_file')
        remote_file = kwargs.get('remote_file')
        # alias = kwargs.get('alias', "default")
        # was_ssh_alias = kwargs.get('was_ssh_alias', "default")
        if node_type.lower() == 'was_node':
            # self.netact_factory.ta_netact.store.get(alias).was_ssh[was_ssh_alias].put_file(local_file=local_file,
            #                                                                        remote_file=remote_file)
            self.netact_factory.netact.get_node('cmwas').put_file(local_file=local_file, remote_file=remote_file)
            # raise DeprecationWarning("ta_netact.store.get(alias).was_ssh[was_ssh_alias] there is no equivalent in "
            #                          "taf.nms.netact to get the sshConnection object")

