    def teardown_ems(self, **kwargs):
        """Teardown ems"""
        config_device = kwargs.get('config_device')
        tool_config = get_config_variable(['ems', config_device])
        alias = kwargs.get('alias', "default")
        self._restore_hosts_on_setup_pc()
        # self.netact_factory.netact.clean_all(alias=alias)
        if not self.netact_factory.netact.delete_node(service_name='cmwas', alias=alias):
            raise FailedToDeleteNetactNode("Failed to delete cmwas node")
        if not self.netact_factory.netact.delete_node(service_name='fmwas', alias=alias):
            raise FailedToDeleteNetactNode("Failed to delete fmwas node")
        if not self.netact_factory.netact.delete_node(service_name='cls-services', alias=alias) and tool_config.get(
                'cls_host'):
            raise FailedToDeleteNetactNode("Failed to delete cls-services node")
